def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def workspace_unchanged(ws):
    root = Path(ws)
    grading_response_name = "answer" + ".md"
    actual_files = {
        path.relative_to(root).as_posix()
        for path in root.rglob("*")
        if path.is_file() and path.name != grading_response_name
    }
    expected_files = set(EXPECTED_FILES)
    if actual_files != expected_files:
        missing = sorted(expected_files - actual_files)
        extra = sorted(actual_files - expected_files)
        return {"score": 0, "detail": f"工作区文件集合变化；缺失={missing}，新增={extra}"}

    changed = [
        relative_path
        for relative_path, expected_hash in EXPECTED_FILES.items()
        if _sha256(root / relative_path) != expected_hash
    ]
    if changed:
        return {"score": 0, "detail": f"工作区文件内容被修改：{changed}"}
    return {"score": 1, "detail": "除评分回复文件外，工作区文件集合与内容均未变化"}

