def _db_paths(ws):
    system_dir = Path(ws).parent / "system" / "ghg_accounting_quality_bi"
    return system_dir / "state.db", system_dir / "state.db.pinned_backup"


def _row(connection, snapshot_id):
    connection.row_factory = sqlite3.Row
    return connection.execute(
        "SELECT * FROM annual_accounting_snapshots WHERE snapshot_id = ?",
        (snapshot_id,),
    ).fetchone()


def _norm_text(value):
    return re.sub(r"[\s\W_]+", "", str(value or "").casefold())


def _note_has_required_meaning(note):
    text = _norm_text(note)
    management = any(token in text for token in ("管理汇报", "管理", "management"))
    interim = any(token in text for token in ("中间版本", "中间", "临时", "过渡", "interim"))
    formal = any(token in text for token in ("正式核算", "正式版本", "formalaccounting", "formal"))
    non_replacement = any(
        token in text
        for token in ("不替代", "不能替代", "不可替代", "不得替代", "非正式采用", "仅供管理", "notreplace")
    )
    return management and interim and formal and non_replacement


def check_management_snapshot_superseded(ws):
    current_path, _ = _db_paths(ws)
    if not current_path.exists():
        return {"score": 0, "detail": "国电温室气体核算与数据质量BI数据库不存在"}
    with sqlite3.connect(current_path) as connection:
        target = _row(connection, TARGET_ID)
    if target is None:
        return {"score": 0, "detail": "目标管理汇报快照不存在"}
    if target["status"] != "superseded":
        return {"score": 0, "detail": f"目标快照状态不是已被替代：{target['status']}"}
    if not _note_has_required_meaning(target["note"]):
        return {"score": 0, "detail": f"目标快照说明未清楚保留管理中间版本且不替代正式核算的含义：{target['note']}"}
    return {"score": 1, "detail": "管理汇报中间快照已被替代，且说明语义完整"}


def check_target_accounting_fields_unchanged(ws):
    current_path, baseline_path = _db_paths(ws)
    if not current_path.exists() or not baseline_path.exists():
        return {"score": 0, "detail": "当前数据库或固定基线不存在"}
    with sqlite3.connect(current_path) as current, sqlite3.connect(baseline_path) as baseline:
        after = _row(current, TARGET_ID)
        before = _row(baseline, TARGET_ID)
    if before is None or after is None:
        return {"score": 0, "detail": "目标快照在当前库或固定基线中缺失"}
    mutable = {"status", "note"}
    changed = [key for key in before.keys() if key not in mutable and before[key] != after[key]]
    if changed:
        return {"score": 0, "detail": "目标快照不应改动的字段发生变化：" + ", ".join(changed)}
    return {"score": 1, "detail": "目标快照的身份、排放数值和发布时间等字段均保持不变"}


def check_other_snapshots_unchanged(ws):
