"""Deterministic post-state checks for the Kingdee reconciliation mutation."""
import sqlite3
from pathlib import Path


TARGET_IDS = {"RECON-UCI-201101-02", "RECON-UCI-201110-11"}
EXPECTED_NON_TARGET = {
    "2010-12": "MATCHED", "2011-02": "MATCHED", "2011-03": "MATCHED",
    "2011-04": "MATCHED", "2011-05": "MATCHED", "2011-06": "MATCHED",
    "2011-07": "MATCHED", "2011-08": "MATCHED", "2011-09": "MATCHED",
    "2011-11": "MATCHED", "2011-12": "MATCHED", "2012-01": "DRAFT",
    "2012-03": "DRAFT"
}


def _db(ws):
    path = Path(ws).parent / "system" / "kingdee_sales_ledger" / "state.db"
    con = sqlite3.connect(path)
    con.row_factory = sqlite3.Row
    return con


def _valid_reason(reason):
    text = "".join(str(reason or "").split()).lower()
    return "取消" in text and "净额" in text and "复核" in text


def _check_target(ws, recon_id, month_id):
    with _db(ws) as con:
        row = con.execute(
            "SELECT recon_status FROM uci_monthly_reconciliation WHERE recon_id=? AND month_id=?",
            (recon_id, month_id),
        ).fetchone()
        audits = con.execute(
            "SELECT reason, recon_status FROM reconciliation_status_audit "
            "WHERE recon_id=? ORDER BY audit_id DESC LIMIT 1", (recon_id,)
        ).fetchone()
    if not row:
        return {"score": 0, "detail": f"missing target {recon_id}"}
    if row["recon_status"] != "DRAFT":
        return {"score": 0, "detail": f"{recon_id} status={row['recon_status']}"}
    if not audits or audits["recon_status"] != "DRAFT" or not _valid_reason(audits["reason"]):
        return {"score": 0, "detail": f"{recon_id} audit reason/status mismatch"}
    return {"score": 1, "detail": f"{month_id} target is DRAFT with required audit reason"}


def check_jan_reopened(ws):
    return _check_target(ws, "RECON-UCI-201101-02", "2011-01")


def check_oct_reopened(ws):
    return _check_target(ws, "RECON-UCI-201110-11", "2011-10")


def check_status_audits(ws):
    with _db(ws) as con:
        rows = con.execute(
            "SELECT recon_id, previous_status, recon_status, reason "
            "FROM reconciliation_status_audit WHERE recon_id IN (?,?) "
            "ORDER BY recon_id, audit_id",
            tuple(sorted(TARGET_IDS)),
        ).fetchall()
    latest = {row["recon_id"]: row for row in rows}
    if set(latest) != TARGET_IDS:
        return {"score": 0, "detail": f"audit targets={sorted(latest)}"}
    for recon_id, row in latest.items():
        if row["previous_status"] != "EXCEPTION_CANCEL_SCOPE" or row["recon_status"] != "DRAFT" or not _valid_reason(row["reason"]):
            return {"score": 0, "detail": f"bad audit for {recon_id}"}
    return {"score": 1, "detail": "both target transitions have the required audit trail"}


def check_unrelated_records_unchanged(ws):
    with _db(ws) as con:
        recon_count = con.execute("SELECT COUNT(*) FROM uci_monthly_reconciliation").fetchone()[0]
        batch_count = con.execute("SELECT COUNT(*) FROM uci_transaction_batch_detail").fetchone()[0]
        rows = con.execute(
            "SELECT month_id, recon_status FROM uci_monthly_reconciliation "
            "WHERE recon_id NOT IN (?,?)", tuple(sorted(TARGET_IDS))
        ).fetchall()
    statuses = {row["month_id"]: row["recon_status"] for row in rows}
    if recon_count != 15 or batch_count != 339:
        return {"score": 0, "detail": f"row counts changed: recon={recon_count}, batches={batch_count}"}
    if statuses != EXPECTED_NON_TARGET:
        return {"score": 0, "detail": "a non-target reconciliation status changed"}
    return {"score": 1, "detail": "non-target reconciliation rows and transaction batch count unchanged"}

